SELECT `form`.`id`, `base`.`id`, 'form_of', '{}'
FROM `form_seed`
INNER JOIN `master_data` AS `form` ON `form`.`category` = 'form' AND `form`.`name` = `form_seed`.`form_name`
INNER JOIN `master_data` AS `base` ON `base`.`category` IN ('pokemon', 'form') AND `base`.`name` = `form_seed`.`base_name`
WHERE 1 = 1
ON CONFLICT (`source_id`, `target_id`, `kind`) DO NOTHING;
--> statement-breakpoint

SELECT `regulation`.`id`, `form`.`id`, 'allows_form', '{}'
FROM `master_data` AS `regulation`
CROSS JOIN `master_data` AS `form`
WHERE `regulation`.`category` = 'regulation'
  AND `regulation`.`name` = 'Regulation M-B'
  AND `form`.`category` = 'form'
ON CONFLICT (`source_id`, `target_id`, `kind`) DO NOTHING;
